class SeparationController extends Controller {
 private $model;private $notes;
 public function __construct(){$this->model=new Separation();$this->notes=new Notification();}
 public function index(){Auth::requireAuth();if(Auth::can('approve_department_clearance')&&!Auth::isHR()&&empty(Auth::user()['employee_id'])){$this->assigned();return;}$admin=Auth::isHR();$this->view('separation/index',['is_admin'=>$admin,'separations'=>$this->model->getSeparationsWithDetails($admin?null:Auth::employeeId()),'employees'=>$admin?(new Employee())->getAllWithDetails():[],'departments'=>$admin?$this->model->db->fetchAll('SELECT id,name FROM departments ORDER BY name'):[],'approvers'=>$admin?$this->approvers():[]]);}
 public function assigned(){
  Auth::requirePermission('approve_department_clearance');
  $this->view('separation/assigned',['assigned_clearances'=>$this->model->assignedItems(Auth::user()['id'])]);
