 public function clearance(){
  Auth::requireAuth();$id=(int)($_GET['id']??0);$sep=$this->model->details($id);
  if(!$sep){http_response_code(404);exit('Separation record not found.');}
  $owner=(int)(Auth::user()['employee_id']??0)>0&&(int)$sep['employee_id']===(int)Auth::user()['employee_id'];
  if(!Auth::isHR()&&!$owner){
   if(!Auth::can('approve_department_clearance'))Auth::deny();
   $items=$this->model->assignedItems(Auth::user()['id'],$id);if(!$items)Auth::deny();
   $this->view('separation/assigned',['assigned_clearances'=>$items]);return;
  }
  $this->view('separation/clearance',['is_admin'=>Auth::isHR(),'can_update_clearance'=>Auth::isHR(),'current_user_id'=>(int)Auth::user()['id'],'separation'=>$sep,'clearances'=>$this->model->getClearanceStatus($sep['id']),'assets'=>$this->model->getAssetReturns($sep['id']),'exit_interview'=>$this->model->getExitInterview($sep['id']),'departments'=>Auth::isHR()?$this->model->db->fetchAll('SELECT id,name FROM departments ORDER BY name'):[],'approvers'=>Auth::isHR()?$this->approvers():[]]);
 }
 public function coe(){Auth::requireAuth();$sep=$this->owned((int)($_GET['id']??0));if($sep['status']!=='Completed')Auth::deny('Certificate is available after separation completion.');$this->view('separation/coe',['separation'=>$sep]);}
 public function initiate(){$this->employeePost();$employee=Auth::employeeId();$type=sanitize_input($_POST['separation_type']??'');if(!in_array($type,['Resignation','End of Contract','Retirement','Termination','Other'],true))$this->json('error','Invalid separation type.',[],422);$reason=trim($_POST['reason']??'');$remarks=trim($_POST['employee_remarks']??'');$date=$_POST['proposed_last_working_date']??'';if($reason===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$date<date('Y-m-d'))$this->json('error','Reason and a valid proposed last working date are required.',[],422);if(mb_strlen($remarks)>2000)$this->json('error','Remarks must not exceed 2,000 characters.',[],422);$file=null;try{[$file,$original]=$this->upload('resignation_letter','separations',true);$id=$this->model->submitRequest($employee,$type,$reason,$remarks,$date,$file,$original);$this->notes->createForAdmins('New separation request','Employee ID '.$employee.' submitted a '.$type.' request.','warning','index.php?page=separation_clearance&id='.$id,'separation',$id);AuditLogger::log('SUBMIT_SEPARATION','Separation Management','Submitted separation ID '.$id,null,['record_type'=>'separation','record_id'=>$id,'new_value'=>['separation_type'=>$type,'proposed_last_working_date'=>$date,'reason'=>$reason,'employee_remarks'=>$remarks?:null]]);$this->json('success','Separation request submitted.',['id'=>$id]);}catch(Throwable $e){$this->remove($file);$this->json('error',$e->getMessage(),[],422);}}
 public function review(){$this->adminPost();$id=(int)($_POST['id']??0);$to=sanitize_input($_POST['status']??'');$sep=$this->model->details($id);if(!$sep)$this->json('error','Separation request not found.',[],404);$allowed=['Submitted'=>['Under Review','Approved','Rejected','Cancelled'],'Under Review'=>['Approved','Rejected','Cancelled'],'Approved'=>['Processing','Cancelled'],'Processing'=>['Clearance Ongoing']];if(!in_array($to,$allowed[$sep['status']]??[],true))$this->json('error','Invalid separation status transition.',[],422);$remarks=trim($_POST['admin_remarks']??'');if($to==='Rejected'&&$remarks==='')$this->json('error','Rejection remarks are required.',[],422);$data=['status'=>$to,'admin_remarks'=>$remarks,'reviewed_by'=>Auth::user()['id'],'reviewed_at'=>date('Y-m-d H:i:s')];if($to==='Approved'){$date=$_POST['final_working_date']??'';if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$this->json('error','Final working date is required.',[],422);$data['final_working_date']=$date;$data['effective_date']=$date;}$this->model->update($id,$data);$this->notify($sep,'Separation '.$to,'Your separation request is now '.$to.'.'.($remarks?' Remarks: '.$remarks:''),in_array($to,['Rejected','Cancelled'],true)?'warning':'info');AuditLogger::log('SEPARATION_'.strtoupper(str_replace(' ','_',$to)),'Separation Management','Separation ID '.$id.' changed from '.$sep['status'].' to '.$to,null,['record_type'=>'separation','record_id'=>$id,'old_value'=>['status'=>$sep['status']],'new_value'=>['status'=>$to,'final_working_date'=>$data['final_working_date']??null,'remarks'=>$remarks]]);$this->json('success','Request marked '.$to.'.');}
 public function generateClearance(){
  $this->adminPost();$id=(int)($_POST['id']??0);$items=[];
  foreach(array_keys((array)($_POST['include']??[])) as $departmentId){$departmentId=(int)$departmentId;$items[]=['department_id'=>$departmentId,'responsible_user_id'=>(int)($_POST['responsible'][$departmentId]??0),'clearance_requirement'=>trim($_POST['requirement'][$departmentId]??''),'is_mandatory'=>isset($_POST['mandatory'][$departmentId])?1:0];}
  if(!$items)$this->json('error','Select at least one participating department.',[],422);
  try{$count=$this->model->createClearance($id,$items);$sep=$this->model->details($id);$this->notify($sep,'Exit clearance started','Your '.$count.'-department clearance checklist is now active.','info');$this->notes->createForAdmins('Pending exit clearance','Separation ID '.$id.' has '.$count.' pending department clearance items.','warning','index.php?page=separation_clearance&id='.$id,'separation',$id);foreach($this->model->getClearanceStatus($id) as $item){$this->notes->createForUser((int)$item['responsible_user_id'],'Clearance responsibility assigned',$item['department_name'].' clearance for '.$sep['first_name'].' '.$sep['last_name'].' requires your attention.','info','index.php?page=separation_clearance&id='.$id,'separation',(int)$item['id']);AuditLogger::log('CLEARANCE_RESPONSIBLE_PERSON_ASSIGNED','Separation Management','Responsible user assigned to clearance ID '.$item['id'],null,['record_type'=>'clearance','record_id'=>(int)$item['id'],'new_value'=>['responsible_user_id'=>(int)$item['responsible_user_id']]]);}AuditLogger::log('CREATE_EXIT_CLEARANCE','Separation Management','Generated '.$count.' configured clearance items for separation ID '.$id,null,['record_type'=>'separation','record_id'=>$id,'new_value'=>['clearance_items'=>$count]]);$this->notifyFinalEligibility($id);$this->json('success','Exit clearance generated from the selected departments and approvers.');}catch(Throwable $e){$this->json('error',$e->getMessage(),[],422);}
 }
 public function updateClearance(){
  $this->clearancePost();$id=(int)($_POST['clearance_id']??0);$status=sanitize_input($_POST['status']??'');if(!in_array($status,['Pending','Cleared','With Accountability'],true))$this->json('error','Invalid clearance status.',[],422);$c=$this->model->getClearance($id);if(!$c)$this->json('error','Clearance item not found.',[],404);$admin=Auth::isHR();if(!$admin&&(int)$c['responsible_user_id']!==(int)Auth::user()['id'])$this->json('error','Only the assigned responsible person may update this clearance item.',[],403);
  try{$this->model->assertClearanceMutable((int)$c['separation_id']);}catch(Throwable $e){$this->json('error',$e->getMessage(),[],422);}
  $departmentId=$admin?(int)($_POST['department_id']??0):(int)$c['department_id'];$department=$this->model->db->fetchOne('SELECT id,name FROM departments WHERE id=?',[$departmentId]);$responsible=$admin?(int)($_POST['responsible_user_id']??0):(int)$c['responsible_user_id'];$person=$this->model->authorizedApprover($responsible,(int)$c['employee_id']);$requirement=$admin?trim($_POST['clearance_requirement']??''):(string)$c['clearance_requirement'];$account=trim($_POST['accountability_details']??'');$mandatory=$admin?(!empty($_POST['is_mandatory'])?1:0):(int)$c['is_mandatory'];$comments=trim($_POST['comments']??'');
  if(!$department||!$person)$this->json('error','Select a valid department and authorized responsible person.',[],422);if($requirement===''||mb_strlen($requirement)>180)$this->json('error','A clearance requirement of up to 180 characters is required.',[],422);if($status==='With Accountability'&&$account==='')$this->json('error','Accountability details are required.',[],422);if($status==='Cleared'&&$account!=='')$this->json('error','Resolve the accountability details before marking this item Cleared.',[],422);if($this->model->db->fetchOne('SELECT id FROM clearances WHERE separation_id=? AND department_name=? AND id<>?',[$c['separation_id'],$department['name'],$id]))$this->json('error','This department already has a clearance item.',[],422);
  $data=['department_id'=>(int)$department['id'],'department_name'=>$department['name'],'responsible_user_id'=>$responsible,'clearance_requirement'=>$requirement,'is_mandatory'=>$mandatory,'status'=>$status,'accountability_details'=>$account?:null,'comments'=>$comments?:null,'cleared_by'=>$status==='Cleared'?Auth::user()['full_name']:null,'verified_by_user_id'=>$status==='Cleared'?Auth::user()['id']:null,'clearance_date'=>$status==='Cleared'?date('Y-m-d H:i:s'):null];$this->model->db->update('clearances',$data,'id=?',[$id]);$sep=$this->model->details($c['separation_id']);
  if((int)$c['responsible_user_id']!==$responsible){$this->notes->createForUser($responsible,'Clearance responsibility assigned',$department['name'].' clearance for '.$sep['first_name'].' '.$sep['last_name'].' requires your attention.','info','index.php?page=separation_clearance&id='.$sep['id'],'separation',$id);AuditLogger::log('CLEARANCE_RESPONSIBLE_PERSON_ASSIGNED','Separation Management','Responsible user updated for clearance ID '.$id,null,['record_type'=>'clearance','record_id'=>$id,'old_value'=>['responsible_user_id'=>$c['responsible_user_id']],'new_value'=>['responsible_user_id'=>$responsible]]);}
  if($c['clearance_requirement']!==$requirement||$c['department_name']!==$department['name']||(int)$c['is_mandatory']!==$mandatory)AuditLogger::log('CLEARANCE_REQUIREMENT_UPDATED','Separation Management','Clearance configuration updated for clearance ID '.$id,null,['record_type'=>'clearance','record_id'=>$id,'old_value'=>['department'=>$c['department_name'],'requirement'=>$c['clearance_requirement'],'mandatory'=>(int)$c['is_mandatory']],'new_value'=>['department'=>$department['name'],'requirement'=>$requirement,'mandatory'=>$mandatory]]);
  if($c['status']!==$status||($c['comments']??'')!==$comments||($c['accountability_details']??'')!==$account){$this->notify($sep,'Clearance updated',$department['name'].' clearance is now '.$status.'.',$status==='Cleared'?'success':'warning');AuditLogger::log('CLEARANCE_STATUS_UPDATED','Separation Management','Clearance ID '.$id.' changed from '.$c['status'].' to '.$status,null,['record_type'=>'clearance','record_id'=>$id,'old_value'=>['status'=>$c['status']],'new_value'=>['status'=>$status]]);}
  $this->notifyFinalEligibility((int)$c['separation_id']);$this->json('success','Department clearance updated.');
 }
 public function uploadClearanceDocument(){$this->employeePost();$id=(int)($_POST['clearance_id']??0);$c=$this->model->getClearance($id);if(!$c)$this->json('error','Clearance item not found.',[],404);Auth::requireOwnership($c['employee_id']);try{[$file,$name]=$this->upload('clearance_document','clearance',true);$this->model->db->update('clearances',['required_document_file'=>$file,'required_document_original_name'=>$name,'document_uploaded_at'=>date('Y-m-d H:i:s')],'id=?',[$id]);AuditLogger::log('UPLOAD_CLEARANCE_DOCUMENT','Separation Management','Uploaded document for clearance ID '.$id);$this->json('success','Clearance document uploaded.');}catch(Throwable $e){$this->json('error',$e->getMessage(),[],422);}}
 public function saveAsset(){$this->adminPost();$id=(int)($_POST['id']??0);$separationId=(int)($_POST['separation_id']??0);try{$separation=$this->model->assertClearanceMutable($separationId);}catch(Throwable $e){$this->json('error',$e->getMessage(),[],422);}$old=$id?$this->model->db->fetchOne('SELECT * FROM asset_returns WHERE id=? AND separation_id=?',[$id,$separationId]):null;if($id&&!$old)$this->json('error','Accountability record not found.',[],404);$returned=isset($_POST['returned'])?1:0;$data=['item_name'=>sanitize_input($_POST['item_name']??''),'serial_no'=>sanitize_input($_POST['serial_no']??''),'condition_status'=>sanitize_input($_POST['condition_status']??'Good'),'returned'=>$returned,'remarks'=>trim($_POST['remarks']??''),'verified_by'=>Auth::user()['full_name'],'verified_by_user_id'=>Auth::user()['id'],'returned_at'=>$returned?date('Y-m-d H:i:s'):null];if($data['item_name']==='')$this->json('error','Asset or accountability name is required.',[],422);if($id)$this->model->db->update('asset_returns',$data,'id=?',[$id]);else{$data['separation_id']=$separationId;$id=$this->model->db->insert('asset_returns',$data);}$action=!$old?'ACCOUNTABILITY_ADDED':(!$old['returned']&&$returned?'ACCOUNTABILITY_RESOLVED':($old['returned']&&!$returned?'ACCOUNTABILITY_REOPENED':'ASSET_RETURN_RECORDED'));AuditLogger::log($action,'Separation Management','Accountability ID '.$id.' saved for separation ID '.$separationId,null,['record_type'=>'asset_return','record_id'=>$id,'old_value'=>$old?['returned'=>(int)$old['returned']]:null,'new_value'=>['returned'=>$returned]]);if($returned&&$action!=='ASSET_RETURN_RECORDED')AuditLogger::log('ASSET_RETURN_RECORDED','Separation Management','Asset return recorded for accountability ID '.$id,null,['record_type'=>'asset_return','record_id'=>$id,'new_value'=>['returned'=>1]]);$this->notify($separation,$returned?'Accountability resolved':'Accountability requires action',$data['item_name'].' is '.($returned?'recorded as returned.':'still outstanding.'),$returned?'success':'warning');$this->notifyFinalEligibility($separationId);$this->json('success','Accountability saved.');}
 public function saveInterview(){$this->adminPost();$id=(int)($_POST['separation_id']??0);$data=['reason_category'=>sanitize_input($_POST['reason_category']??'Other'),'feedback'=>trim($_POST['feedback']??''),'rehire_recommendation'=>sanitize_input($_POST['rehire_recommendation']??'Conditional'),'conducted_at'=>date('Y-m-d H:i:s'),'recorded_by'=>Auth::user()['id'],'admin_remarks'=>trim($_POST['admin_remarks']??'')];$old=$this->model->getExitInterview($id);if($old)$this->model->db->update('exit_interviews',$data,'separation_id=?',[$id]);else{$data['separation_id']=$id;$this->model->db->insert('exit_interviews',$data);}AuditLogger::log('RECORD_EXIT_INTERVIEW','Separation Management','Exit interview saved for separation ID '.$id);$this->json('success','Exit interview recorded.');}
 public function complete(){$this->adminPost();$id=(int)($_POST['id']??0);$before=$this->model->details($id);try{$sep=$this->model->complete($id,Auth::user()['id']);$this->notify($sep,'Separation completed','Final HR clearance is complete. Your final clearance is available.','success');$this->notes->createForAdmins('Final clearance completed','Separation ID '.$id.' is ready for Payroll processing.','success','index.php?page=separation_clearance&id='.$id,'separation',$id);AuditLogger::log('FINAL_CLEARANCE_COMPLETED','Separation Management','Completed final clearance for separation ID '.$id,null,['record_type'=>'separation','record_id'=>$id,'old_value'=>['status'=>$before['status']??null],'new_value'=>['status'=>'Completed','final_pay_processing_status'=>'Ready for Payroll']]);$this->json('success','Final HR clearance completed.');}catch(Throwable $e){AuditLogger::log('FINAL_CLEARANCE_BLOCKED','Separation Management','Final clearance blocked for separation ID '.$id,null,['record_type'=>'separation','record_id'=>$id,'new_value'=>['reason'=>$e->getMessage()]]);$this->json('error',$e->getMessage(),[],422);}}
 public function archive(){$this->adminPost();$id=(int)($_POST['id']??0);$sep=$this->model->details($id);if(!$sep||$sep['status']!=='Completed')$this->json('error','Only completed separations may be archived.',[],422);$this->model->update($id,['archived_at'=>date('Y-m-d H:i:s')]);AuditLogger::log('ARCHIVE_SEPARATION','Separation Management','Archived separation ID '.$id);$this->json('success','Separation archived.');}
 public function finalClearance(){Auth::requireAuth();$sep=$this->owned((int)($_GET['id']??0));if($sep['status']!=='Completed')Auth::deny('Final clearance is available after completion.');$items=$this->model->getClearanceStatus($sep['id']);$companySetting=$this->model->db->fetchOne("SELECT setting_value FROM system_settings WHERE setting_key='company_name'");$companyName=trim((string)($companySetting['setting_value']??''))?:'Great Solomon Manpower Services Inc.';$logoPath=ROOT_PATH.'assets/images/logo-icon.svg';$logoData=is_file($logoPath)?'data:image/svg+xml;base64,'.base64_encode(file_get_contents($logoPath)):'';header('Content-Type:text/html; charset=UTF-8');header('Content-Disposition:attachment; filename="final-clearance-'.preg_replace('/[^A-Za-z0-9_-]/','',$sep['employee_code']).'.html"');header('X-Content-Type-Options:nosniff');require APP_PATH.'Views/separation/final_clearance_document.php';exit;}
 public function downloadFile(){Auth::requireAuth();$kind=$_GET['kind']??'resignation';if($kind==='clearance'){$c=$this->model->getClearance((int)($_GET['id']??0));if(!$c)Auth::deny();$owner=(int)(Auth::user()['employee_id']??0)===(int)$c['employee_id'];$assigned=Auth::can('approve_department_clearance')&&(int)$c['responsible_user_id']===(int)Auth::user()['id']&&!$owner;if(!Auth::isHR()&&!$owner&&!$assigned)Auth::deny();$path=$c['required_document_file'];$name=$c['required_document_original_name'];}else{$s=$this->owned((int)($_GET['id']??0));$path=$s['resignation_file'];$name=$s['resignation_original_name'];}$this->sendFile($path,$name);}
 private function owned($id){$s=$this->model->details($id,Auth::isHR()?null:Auth::employeeId());if(!$s){http_response_code(404);exit('Separation record not found.');}return $s;}private function notify($s,$title,$message,$type){$this->notes->createForEmployee($s['employee_id'],$title,$message,$type,'index.php?page=separation_clearance&id='.$s['id'],'separation',$s['id']);}
 private function approvers(){return $this->model->db->fetchAll("SELECT u.id,u.employee_id,u.username,COALESCE(NULLIF(CONCAT(e.first_name,' ',e.last_name),' '),u.username) name,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN employees e ON e.id=u.employee_id WHERE u.is_active=1 AND r.name IN ('HR Manager','HR Officer','Department Head') ORDER BY name");}
 private function notifyFinalEligibility($separationId){if($this->model->blockers($separationId)>0)return;$sep=$this->model->details($separationId);if(!$sep||$sep['status']!=='Clearance Ongoing')return;$exists=$this->model->db->fetchOne("SELECT id FROM notifications WHERE title='Final clearance ready' AND module='separation' AND related_id=?",[$separationId]);if($exists)return;$this->notify($sep,'Final clearance ready','All mandatory clearance items and asset accountabilities are resolved. Final HR clearance may now be completed.','success');$this->notes->createForAdmins('Final clearance ready','Separation ID '.$separationId.' is eligible for final HR clearance.','success','index.php?page=separation_clearance&id='.$separationId,'separation',$separationId);}
 private function upload($field,$dir,$required){if(!isset($_FILES[$field])||$_FILES[$field]['error']===UPLOAD_ERR_NO_FILE){if($required)throw new RuntimeException('Required PDF/JPG/PNG file is missing.');return [null,null];}$f=$_FILES[$field];if($f['error']!==UPLOAD_ERR_OK||$f['size']<1||$f['size']>5242880)throw new RuntimeException('File must be 5 MB or less.');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$map=['pdf'=>'application/pdf','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png'];if(!isset($map[$ext])||$map[$ext]!==$mime)throw new RuntimeException('Only valid PDF, JPG, or PNG files are accepted.');$root=ROOT_PATH.'public/uploads/'.$dir.'/';if(!is_dir($root)&&!mkdir($root,0755,true))throw new RuntimeException('Unable to prepare upload directory.');$name=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$root.$name))throw new RuntimeException('Unable to store file.');return ['uploads/'.$dir.'/'.$name,preg_replace('/[^A-Za-z0-9._-]+/','-',basename($f['name']))];}
 private function sendFile($stored,$name){if(!$stored){http_response_code(404);exit('File not found.');}$root=realpath(ROOT_PATH.'public/uploads');$path=realpath(ROOT_PATH.'public/'.ltrim(str_replace(chr(92),'/',$stored),'/'));if(!$root||!$path||!is_file($path)||strpos($path,$root.DIRECTORY_SEPARATOR)!==0){http_response_code(404);exit('File not found.');}header('Content-Type:'.(mime_content_type($path)?:'application/octet-stream'));header('Content-Disposition:attachment; filename="'.basename($name?:$path).'"');readfile($path);exit;}private function remove($path){if($path&&is_file(ROOT_PATH.'public/'.$path))unlink(ROOT_PATH.'public/'.$path);}private function adminPost(){Auth::requirePermission('manage_separation');Auth::requireMethod('POST');$this->csrf();}private function clearancePost(){Auth::requireAuth();if(!Auth::can('manage_separation')&&!Auth::can('approve_department_clearance'))Auth::deny();Auth::requireMethod('POST');$this->csrf();}private function employeePost(){Auth::requirePermission('submit_separation');Auth::requireMethod('POST');$this->csrf();}private function csrf(){if(!verify_csrf_token($_POST['csrf_token']??''))$this->json('error','Invalid CSRF token.',[],403);}
